      const style = kubaiStyle();
      const runtime = window.__Kubai;
      let map = {};
      let disposed = false;

      const specOf = row => {
        const id = (row.dataset.rowKey || "").replace(/^workspace:/, "");
        const spec = map[id];
        // 老数据里存的是 Phosphor 的名字（folder / ghost…），那些继续走单色 mask。
        if (spec && typeof spec.icon === "string" && spec.icon && !KUBAI_ORDER.includes(spec.icon)) return null;
        const icon = spec && KUBAI_ORDER.includes(spec.icon) ? spec.icon : KUBAI_DEFAULT_ICON;
        const color = spec && typeof spec.color === "string" && spec.color ? spec.color : "";
        return { icon, color: color || kubaiAccent(icon) };
      };

      // 退回单色图标时，必须把 data-kubai-ready 撤掉，否则原来的 mask 图标会被藏住。
      const unmountRow = row => {
        const slot = row.querySelector(".kubai-slot");
        if (slot) slot.remove();
        delete row.dataset.kubaiReady;
        delete row.dataset.kubaiIcon;
        delete row.dataset.kubaiColor;
        row.__kubaiInst = null;
      };

      const mountRow = row => {
        const spec = specOf(row);
        if (!spec) { unmountRow(row); return; }
        const folder = row.querySelector(".JoiKIa_folder");
        if (!folder) return;
        const done = folder.querySelector(".kubai-slot");
        if (done && row.dataset.kubaiIcon === spec.icon && row.dataset.kubaiColor === spec.color) return;
        if (done) done.remove();
        delete row.dataset.kubaiReady;
        const icon = runtime.byName(spec.icon);
        if (!icon) return;
        const holder = document.createElement("span");
        holder.className = "kubai-slot";
        folder.appendChild(holder);
        try {
          const inst = runtime.mount(icon, holder, spec.color);
          const svg = holder.querySelector("svg");
          if (svg) { svg.setAttribute("width", "18"); svg.setAttribute("height", "18"); }
          row.__kubaiInst = inst;
          row.dataset.kubaiIcon = spec.icon;
          row.dataset.kubaiColor = spec.color;
          row.dataset.kubaiReady = "1";
        } catch (error) {
          console.warn("[dsh-dune] 动态图标挂载失败", error);
          holder.remove();
          return;
        }
        if (!row.dataset.kubaiBound) {
          row.dataset.kubaiBound = "1";
          row.addEventListener("pointerenter", () => {
            const current = row.__kubaiInst;
            if (current) { current.hover++; runtime.go(current); }
          });
          row.addEventListener("pointerleave", () => {
            const current = row.__kubaiInst;
            if (current) { current.hover = Math.max(0, current.hover - 1); runtime.go(current); }
          });
        }
      };

